#include "EmbeddedImages.hpp"
#include <assert.h>
#include <vcruntime_string.h>

#define STB_IMAGE_IMPLEMENTATION
#define STB_IMAGE_RESIZE_IMPLEMENTATION
#include "..\ThirdParty\stb\stb_image.h"
#include "..\ThirdParty\stb\stb_image_resize2.h"

unsigned char* STBResize(const unsigned char* inputPixels, int inputW, int inputH, int inputStrideInBytes,
	unsigned char* outputPixels, int outputW, int outputH, int outputStrideInBytes,
	int numChannels)
{
	return stbir_resize_uint8_linear(inputPixels, inputW, inputH, inputStrideInBytes,
		outputPixels, outputW, outputH, outputStrideInBytes,
		(stbir_pixel_layout)numChannels);
}

unsigned int STBDecompressLength(const unsigned char* input)
{
	return (input[8] << 24) + (input[9] << 16) + (input[10] << 8) + input[11];
}

unsigned char* stb__barrier_out_e, * stb__barrier_out_b;
const unsigned char* stb__barrier_in_b;
unsigned char* stb__dout;
void STBMatch(const unsigned char* data, unsigned int length)
{
	// INVERSE of memmove... write each byte before copying the next...
	assert(stb__dout + length <= stb__barrier_out_e);
	if (stb__dout + length > stb__barrier_out_e) { stb__dout += length; return; }
	if (data < stb__barrier_out_b) { stb__dout = stb__barrier_out_e + 1; return; }
	while (length--) *stb__dout++ = *data++;
}

void STBLit(const unsigned char* data, unsigned int length)
{
	assert(stb__dout + length <= stb__barrier_out_e);
	if (stb__dout + length > stb__barrier_out_e) { stb__dout += length; return; }
	if (data < stb__barrier_in_b) { stb__dout = stb__barrier_out_e + 1; return; }
	memcpy(stb__dout, data, length);
	stb__dout += length;
}

#define stb__in2(x)   ((i[x] << 8) + i[(x)+1])
#define stb__in3(x)   ((i[x] << 16) + stb__in2((x)+1))
#define stb__in4(x)   ((i[x] << 24) + stb__in3((x)+1))

const unsigned char* STBDecompressToken(const unsigned char* i)
{
	if (*i >= 0x20) { // use fewer if's for cases that expand small
		if (*i >= 0x80)       STBMatch(stb__dout - i[1] - 1, i[0] - 0x80 + 1), i += 2;
		else if (*i >= 0x40)  STBMatch(stb__dout - (stb__in2(0) - 0x4000 + 1), i[2] + 1), i += 3;
		else /* *i >= 0x20 */ STBLit(i + 1, i[0] - 0x20 + 1), i += 1 + (i[0] - 0x20 + 1);
	}
	else { // more ifs for cases that expand large, since overhead is amortized
		if (*i >= 0x18)       STBMatch(stb__dout - (stb__in3(0) - 0x180000 + 1), i[3] + 1), i += 4;
		else if (*i >= 0x10)  STBMatch(stb__dout - (stb__in3(0) - 0x100000 + 1), stb__in2(3) + 1), i += 5;
		else if (*i >= 0x08)  STBLit(i + 2, stb__in2(0) - 0x0800 + 1), i += 2 + (stb__in2(0) - 0x0800 + 1);
		else if (*i == 0x07)  STBLit(i + 3, stb__in2(1) + 1), i += 3 + (stb__in2(1) + 1);
		else if (*i == 0x06)  STBMatch(stb__dout - (stb__in3(1) + 1), i[4] + 1), i += 5;
		else if (*i == 0x04)  STBMatch(stb__dout - (stb__in3(1) + 1), stb__in2(4) + 1), i += 6;
	}
	return i;
}

unsigned int SRBAdler32(unsigned int adler32, unsigned char* buffer, unsigned int buflen)
{
	const unsigned long ADLER_MOD = 65521;
	unsigned long s1 = adler32 & 0xffff, s2 = adler32 >> 16;
	unsigned long blocklen = buflen % 5552;

	unsigned long i;
	while (buflen) {
		for (i = 0; i + 7 < blocklen; i += 8) {
			s1 += buffer[0], s2 += s1;
			s1 += buffer[1], s2 += s1;
			s1 += buffer[2], s2 += s1;
			s1 += buffer[3], s2 += s1;
			s1 += buffer[4], s2 += s1;
			s1 += buffer[5], s2 += s1;
			s1 += buffer[6], s2 += s1;
			s1 += buffer[7], s2 += s1;

			buffer += 8;
		}

		for (; i < blocklen; ++i)
			s1 += *buffer++, s2 += s1;

		s1 %= ADLER_MOD, s2 %= ADLER_MOD;
		buflen -= blocklen;
		blocklen = 5552;
	}
	return (unsigned int)(s2 << 16) + (unsigned int)s1;
}

unsigned int STBDecompress(unsigned char* output, const unsigned char* i, unsigned int length)
{
	if (stb__in4(0) != 0x57bC0000) return 0;
	if (stb__in4(4) != 0)          return 0; // error! stream is > 4GB
	const unsigned int olen = STBDecompressLength(i);
	stb__barrier_in_b = i;
	stb__barrier_out_e = output + olen;
	stb__barrier_out_b = output;
	i += 16;

	stb__dout = output;
	for (;;) {
		const unsigned char* old_i = i;
		i = STBDecompressToken(i);
		if (i == old_i) {
			if (*i == 0x05 && i[1] == 0xfa) {
				assert(stb__dout == output + olen);
				if (stb__dout != output + olen) return 0;
				if (SRBAdler32(1, output, olen) != (unsigned int)stb__in4(2))
					return 0;
				return olen;
			}
			else {
				assert(0); /* NOTREACHED */
				return 0;
			}
		}
		assert(stb__dout <= output + olen);
		if (stb__dout > output + olen)
			return 0;
	}
}

Image::Image(const uint32_t width, const uint32_t height,
	const uint32_t compressedSize, const uint8_t* compressedData)
	: m_Width(width), m_Height(height),
	m_IimageCompressedSize(compressedSize), m_image_compressed_data(compressedData)
{
	m_RGBAData = new uint8_t[STBDecompressLength(m_image_compressed_data)];
	STBDecompress(m_RGBAData, m_image_compressed_data, m_IimageCompressedSize);
}

Image::~Image() {
	delete[] m_RGBAData;
}

void Image::Resize(uint32_t newWidth, uint32_t newHeight) {
	uint8_t* temp = new uint8_t[newWidth * newHeight * 4];

	STBResize(m_RGBAData, m_Width, m_Height, 0, temp, newWidth, newHeight, 0, 4);

	m_Width = newWidth;
	m_Height = newHeight;

	delete[] m_RGBAData;
	m_RGBAData = temp;
}

void Image::ResizeByRatioH(uint32_t newHeight) {
	uint32_t newWidth = uint32_t(float(m_Width) / float(m_Height) * float(newHeight));

	Resize(newWidth, newHeight);
}


void Image::ResizeByRatioW(uint32_t newWidth) {
	uint32_t newHeight = uint32_t(float(m_Height) / float(m_Width) * float(newWidth));

	Resize(newWidth, newHeight);
}

